glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
in vec3 a_position;
in vec2 a_uv0;
in vec4 a_color;
#if USE_TINT
    in vec4 a_color0;
#endif
out vec2 v_uv0;
out vec4 v_color;
#if USE_TINT
    out vec4 v_dark;
#endif
void main () {
    gl_Position = cc_matViewProj * vec4(a_position.xy, 0.0, 1.0);
    v_uv0  = a_uv0;
    v_color = a_color;
    #if USE_TINT
        v_dark = a_color0;
    #endif
}

