uniform sampler2D texture12;
uniform sampler2D texture13;
uniform sampler2D texture14;
uniform sampler2D texture15;
in vec2 v_uv0;
in vec4 v_color;
#if USE_TINT
    in vec4 v_dark;
#endif
vec4 sampleSlot(vec2 encodedUv) {
    float slot = floor(encodedUv.y * 0.5);
    vec2  uv   = vec2(encodedUv.x, encodedUv.y - slot * 2.0);
    if      (slot <  0.5) { return texture2D(texture0,  uv); }
    else if (slot <  1.5) { return texture2D(texture1,  uv); }
    else if (slot <  2.5) { return texture2D(texture2,  uv); }
    else if (slot <  3.5) { return texture2D(texture3,  uv); }
    else if (slot <  4.5) { return texture2D(texture4,  uv); }
    else if (slot <  5.5) { return texture2D(texture5,  uv); }
    else if (slot <  6.5) { return texture2D(texture6,  uv); }
    else if (slot <  7.5) { return texture2D(texture7,  uv); }
    else if (slot <  8.5) { return texture2D(texture8,  uv); }
    else if (slot <  9.5) { return texture2D(texture9,  uv); }
    else if (slot < 10.5) { return texture2D(texture10, uv); }
    else if (slot < 11.5) { return texture2D(texture11, uv); }
    else if (slot < 12.5) { return texture2D(texture12, uv); }
    else if (slot < 13.5) { return texture2D(texture13, uv); }
    else if (slot < 14.5) { return texture2D(texture14, uv); }
    else                  { return texture2D(texture15, uv); }
}
