    vec4 texColor = sampleSlot(v_uv0);
    #if USE_TINT
        float alpha = texColor.a;
        gl_FragColor = vec4(
            ((alpha - 1.0) * v_dark.a + 1.0 - texColor.rgb) * v_dark.rgb
                + texColor.rgb * v_color.rgb,
            alpha * v_color.a
        );
    #else
        gl_FragColor = texColor * v_color;
    #endif
}

